import React from 'react';
import { string, bool } from 'prop-types';
import styled from 'styled-components';
import MDXRenderer from 'gatsby-plugin-mdx/mdx-renderer';
import { MDXProvider } from '@mdx-js/react';

import * as components from '@gympass/yoga';
import * as icons from '@gympass/yoga-icons';
import * as illustrations from '@gympass/yoga-illustrations';
import * as helpers from '@gympass/yoga-helpers';
import * as system from '@gympass/yoga-system';

import {
  CodeBlock,
  PropsTable,
  Table,
  InlineCode,
  TabbedView,
  Tab,
  Redirect,
  Summary,
  Tokens,
} from 'components';

import {
  ComponentTitle,
  SubHeading2,
  SubHeading3,
  SubHeading4,
  Paragraph,
  Img,
  Ul,
} from '../MDXElements/MDXElements';

import {
  Colors,
  Fonts,
  FontSizes,
  FontWeights,
  LineHeights,
  Breakpoints,
  Spacing,
  Borders,
  Elevations,
  Shape,
  ReactInspector,
} from '../Theme/index';

const customComponents = prefix => ({
  h1: props => <ComponentTitle {...props} prefix={prefix} />,
  h2: props => <SubHeading2 {...props} />,
  h3: props => <SubHeading3 {...props} />,
  h4: props => <SubHeading4 {...props} />,
  p: props => <Paragraph {...props} />,
  ul: props => <Ul {...props} />,
  pre: 'div',
  code: props => <CodeBlock {...props} />,
  inlineCode: InlineCode,
  TabbedView: props => <TabbedView {...props} />,
  Tab: props => <Tab {...props} />,
  PropsTable,
  Table,
  img: props => <Img {...props} prefix={prefix} />,
  Redirect: props => <Redirect {...props} />,
  Tokens: props => <Tokens {...props} />,
  TokensColors: props => <Tokens.Colors {...props} />,
  TokensCards: props => <Tokens.Cards {...props} />,
  ThemeColors: props => <Colors {...props} />,
  ThemeFonts: props => <Fonts {...props} />,
  ThemeFontSizes: props => <FontSizes {...props} />,
  ThemeFontWeights: props => <FontWeights {...props} />,
  ThemeLineHeights: props => <LineHeights {...props} />,
  ThemeBreakpoints: props => <Breakpoints {...props} />,
  ThemeSpacing: props => <Spacing {...props} />,
  ThemeBorders: props => <Borders {...props} />,
  ThemeElevations: props => <Elevations {...props} />,
  ThemeShape: props => <Shape {...props} />,
  ThemeInspector: props => <ReactInspector {...props} />,
  ...components,
  ...icons,
  ...illustrations,
  ...helpers,
  ...system,
});

const Wrapper = styled.div`
  display: flex;
  min-height: calc(100vh - 140px);
  grid-area: Documentation;
  padding: 30px 0 30px 100px;

  background-color: ${components.theme.colors.clear};

  @media (max-width: 900px) {
    min-height: calc(100vh - 130px);
    padding: 80px 20px 20px;
  }
`;

const Documentation = ({ mdx, prefix }) => (
  <Wrapper>
    <div style={{ width: '100%' }}>
      <MDXProvider components={customComponents(prefix)}>
        <MDXRenderer>{mdx}</MDXRenderer>
      </MDXProvider>
    </div>
    <Summary />
  </Wrapper>
);

Documentation.propTypes = {
  mdx: string.isRequired,
  prefix: bool.isRequired,
};

export default Documentation;
